-- SEDA TV/REF/LDY: Magalu and Casas Bahia approved cross-field checks.
-- Run with DBeaver after deploying the adapter. Includes recommendation_intent;
-- the earlier recommendation-only setup is not required separately.
-- Scope: inspection D -> source D-1, latest MAIN batch and its MAIN/BSR rows.
-- Summary disappearance: most recent prior record within 5 calendar days;
-- both bodies present before, detailed body still present, summary now missing.
-- Savings/discount rules are intentionally excluded. Other countries unchanged.
-- Repeatable: update existing IDs so manual confirmations remain attached.
BEGIN;
CREATE TEMP TABLE _seda_crossfield_seed (
    product_line text, section_code text, section_name text, table_name text,
    detail_code text, detail_name text, retailer text, validation_type text,
    field1 text, field2 text, error_message text, select_fields text, sort_order integer
) ON COMMIT DROP;

UPDATE public.monitoring_validation_rules AS target
SET section_name = seed.section_name, detail_name = seed.detail_name,
    date_column = 'crawl_strdatetime', product_line = seed.product_line,
    retailer = seed.retailer, field1 = seed.field1, field2 = seed.field2,
    validation_type = seed.validation_type, check_type = 'cross_field',
    error_message = seed.error_message, display_columns = seed.select_fields,
    select_fields = seed.select_fields, query = '', query_detail = '',
    sort_order = seed.sort_order, is_active = TRUE
FROM _seda_crossfield_seed AS seed
WHERE target.rule_type = 'crossfield'
  AND target.section_code = seed.section_code AND target.table_name = seed.table_name
  AND target.detail_code = seed.detail_code
  AND LOWER(REPLACE(BTRIM(target.retailer), ' ', '')) = LOWER(REPLACE(seed.retailer, ' ', ''));

    rule_type, section_code, section_name, detail_code, detail_name,
    table_name, date_column, product_line, retailer, field1, field2,
    validation_type, check_type, error_message, display_columns, select_fields,
    query, query_detail, sort_order, is_active, created_at, created_id
)
SELECT 'crossfield', seed.section_code, seed.section_name, seed.detail_code,
       seed.detail_name, seed.table_name, 'crawl_strdatetime', seed.product_line,
       seed.retailer, seed.field1, seed.field2, seed.validation_type, 'cross_field',
       seed.error_message, seed.select_fields, seed.select_fields,
       '', '', seed.sort_order, TRUE, NOW(), 'setup_seda_crossfield'
FROM _seda_crossfield_seed AS seed
WHERE NOT EXISTS (
    SELECT 1 FROM public.monitoring_validation_rules AS target
    WHERE target.rule_type = 'crossfield'
      AND target.section_code = seed.section_code AND target.table_name = seed.table_name
      AND target.detail_code = seed.detail_code
      AND LOWER(REPLACE(BTRIM(target.retailer), ' ', '')) = LOWER(REPLACE(seed.retailer, ' ', ''))
);

-- Expected: 57 retailer-specific rows, combined into 11 rule cards per product.
SELECT target.section_code, target.retailer, COUNT(*) AS active_rules
FROM public.monitoring_validation_rules target
JOIN _seda_crossfield_seed seed
  ON target.section_code = seed.section_code AND target.table_name = seed.table_name
 AND target.detail_code = seed.detail_code
 AND LOWER(REPLACE(BTRIM(target.retailer), ' ', '')) = LOWER(REPLACE(seed.retailer, ' ', ''))
WHERE target.rule_type = 'crossfield' AND target.is_active
GROUP BY target.section_code, target.retailer
ORDER BY target.section_code, target.retailer;
COMMIT;
